-- Catálogo de centros y subcentros de costos, cargado desde "CENTRO DE COSTOS (55).xlsx"
-- (hoja CENTRO DE COSTOS), para relacionarlos en "Plan de acción y tablero acumulado anual"
-- (S7 id33, PlanPresupuesto.tsx) en vez de un campo de texto libre.
create table if not exists cost_centers (
  id bigint generated always as identity primary key,
  centro text not null,
  subcentro_codigo text not null unique,
  descripcion text,
  responsable text,
  estado text,
  created_at timestamptz not null default now()
);

alter table cost_centers enable row level security;
create policy "public select" on cost_centers for select using (true);

